// プログラムで描いた試しの回答票。人の写真・筆跡・資料は使わない。
// 3394x4800のJPEGにCOM領域を足して6.7MBにする。保管用はPillowで2400px・品質85へ変換。
const JPEG = "";
const STORED_JPEG = "";

export function fictionalStoredPhoto(): Uint8Array {
  return Uint8Array.from(atob(STORED_JPEG), c => c.charCodeAt(0));
}

export function fictionalPhonePhoto(): Uint8Array {
  const source = Uint8Array.from(atob(JPEG), c => c.charCodeAt(0));
  const raw = new Uint8Array(6_700_000);
  raw.set(source.subarray(0, 2));
  let offset = 2;
  let remaining = raw.length - source.length;
  while (remaining > 0) {
    let size = Math.min(65537, remaining);
    if (remaining - size > 0 && remaining - size < 4) size -= 4;
    raw.set([255, 254, (size - 2) >> 8, (size - 2) & 255], offset);
    offset += size; remaining -= size;
  }
  raw.set(source.subarray(2), offset);
  return raw;
}
